sysevent_in_email_action.script:
(function runAction(current, event, email, logger, classifier) {

    // =========================================================
    // 1. STORE EMAIL INFORMATION
    // =========================================================

    current.sender_email = email.from;
    current.raw_text = email.body_text;

    // Store request source
    current.channel = 'inbound_email';

    // Store the original inbound sys_email record ID
    if (typeof sys_email !== 'undefined' && sys_email) {

        current.channel_reference = sys_email.getUniqueValue();

        logger.log(
            'Original inbound email sys_id: ' +
            sys_email.getUniqueValue(),
            'FlowOpsInboundEmail'
        );

    } else {

        logger.log(
            'Could not access original sys_email record.',
            'FlowOpsInboundEmail'
        );

    }


    // =========================================================
    // 2. FIND GUEST USING SENDER EMAIL
    // =========================================================

    var guestGR = new GlideRecord('x_snc_flowops_guest');
    guestGR.addQuery('email', email.from);
    guestGR.query();

    if (guestGR.next()) {

        current.guest = guestGR.getUniqueValue();

    } else {

        logger.log(
            'Guest not found for email: ' + email.from,
            'FlowOpsInboundEmail'
        );

    }


    // =========================================================
    // 3. EXTRACT ROOM NUMBER
    // =========================================================

    var roomNumber = '';

    var roomMatch = email.body_text.match(
        /(?:room|rm)\s*[-:#]?\s*(\d+)/i
    );


    // Check subject if room was not found in body
    if (!roomMatch && email.subject) {

        roomMatch = email.subject.match(
            /(?:room|rm)\s*[-:#]?\s*(\d+)/i
        );

    }


    if (roomMatch) {

        roomNumber = roomMatch[1];

    }


    // =========================================================
    // 4. FIND ROOM USING ROOM NUMBER
    // =========================================================

    if (roomNumber) {

        var roomGR = new GlideRecord('x_snc_flowops_room');
        roomGR.addQuery('room_number', roomNumber);
        roomGR.query();

        if (roomGR.next()) {

            current.room = roomGR.getUniqueValue();

        } else {

            logger.log(
                'Room not found: ' + roomNumber,
                'FlowOpsInboundEmail'
            );

        }

    } else {

        logger.log(
            'No room number found in email.',
            'FlowOpsInboundEmail'
        );

    }


    // =========================================================
    // 5. CREATE GUEST REQUEST
    // =========================================================

    current.insert();


    // =========================================================
    // 6. FIRE EVENT
    // =========================================================

    gs.eventQueue(
        'x_snc_flowops.guest_request_created',
        current,
        email.from,
        current.number
    );


    // =========================================================
    // 7. LOG RESULT
    // =========================================================

    logger.log(
        'Guest Request created: ' + current.number +
        ' from ' + email.from +
        ' for Room ' + roomNumber +
        ' | Channel: ' + current.channel +
        ' | Channel Reference: ' + current.channel_reference,
        'FlowOpsInboundEmail'
    );

})(current, event, email, logger, classifier);
